import requests, json

# Try Nasdaq institutional holdings API with longer timeout
headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
    'Accept': 'application/json',
}

# Nasdaq API for institutional ownership
endpoints = [
    'https://api.nasdaq.com/api/quote/NVDA/institutional-holdings?assetclass=stocks',
    'https://api.nasdaq.com/api/quote/NVDA/holder',
]

for url in endpoints:
    try:
        r = requests.get(url, headers=headers, timeout=30)
        print(f"{url} -> {r.status_code}")
        if r.status_code == 200:
            data = r.json()
            print(json.dumps(data, indent=2)[:2000])
        print()
    except Exception as e:
        print(f"{url} -> ERROR: {e}\n")
